// Parsear la respuesta del agente a JSON
const output = $input.first().json.output || $input.first().json.text || '{}';

let parsed;
try {
  const jsonMatch = output.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    parsed = JSON.parse(output);
  }
} catch (e) {
  parsed = {
    media_type: 'conversation',
    response_text: output || 'Lo siento, no entendí bien. ¿Podrías repetir?'
  };
}

// Normalizar media_type
if (!['video', 'carousel', 'single_image', 'conversation'].includes(parsed.media_type)) {
    // Si la IA inventa un tipo, asumimos conversación o imagen según contexto, 
    // pero por seguridad 'conversation' para no gastar créditos.
    parsed.media_type = 'conversation'; 
    if (!parsed.response_text) parsed.response_text = "Entendido. ¿Qué quieres crear hoy?";
}

return [{ json: parsed }];

