// Guardar en memoria el contenido previo para contexto
// Usamos try-catch porque estos nodos pueden no estar disponibles en esta ejecución
let parsedContent = {};
let originalPrompt = '';

try {
  parsedContent = $('Parsear JSON').first()?.json || {};
} catch (e) {
  // Parsear JSON no disponible en esta ejecución
  parsedContent = {};
}

try {
  originalPrompt = $('Cerebro CM').first()?.json?.input || '';
} catch (e) {
  // Cerebro CM no disponible en esta ejecución
  originalPrompt = '';
}

return [{
  json: {
    waiting_feedback: true,
    original_content: parsedContent,
    original_prompt: originalPrompt,
    chat_id: $json.callback_query?.message?.chat?.id || $json.message?.chat?.id
  }
}];

// Combinar feedback con contenido original para regenerar
const feedback = $json.text || $json.message?.text || '';
const chatId = $json.message?.chat?.id;

// Construir prompt mejorado con el feedback
const enhancedPrompt = `CORRECCIONES DEL USUARIO:
${feedback}

Por favor regenera el contenido aplicando estas correcciones. Mantén el mismo formato de respuesta JSON.`;

return [{
  json: {
    message: {
      text: enhancedPrompt,
      chat: { id: chatId }
    },
    is_revision: true,
    feedback: feedback
  }
}];
